-- SPARK Mathematics original-v2 Questions 3-6 source calibration.
-- Source-authored draft only. Transformation diagrams, triple coordinates,
-- cumulative-frequency cells and freehand/extended methods are NEVER
-- final-scored without authenticated evidence verification.
BEGIN;
DO $math_source$
DECLARE
 v_schemes jsonb := '{"p2-q3-v2::a":[{"code":"B1","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Recognises the transformation as a reflection","check":{"type":"manual-verification","evidence":"Check ''reflection'' or an explicitly equivalent single rigid transformation; a translation or rotation must not receive B1."}},{"code":"B2","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Identifies the y-axis as the mirror line","check":{"type":"manual-verification","evidence":"Check ''y-axis'' or x=0; do not confuse horizontal x-axis y=0 with the mirror line."}},{"code":"B3","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Fully specifies the fixed mirror line x=0","check":{"type":"manual-verification","evidence":"Check complete fixed line x=0 or clearly equivalent construction, including correct correspondence (x,y)→(-x,y); do not grant a second axis mark for unrelated wording."}}],"p2-q3-v2::b":[{"code":"B1","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Translates vertex A(2,2) to (5,-5)","check":{"type":"manual-verification","evidence":"Verify the submitted vertex A or first explicitly ordered vertex is (5,-5), not a coordinate belonging to B or C."}},{"code":"B2","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Translates vertex B(6,2) to (9,-5)","check":{"type":"manual-verification","evidence":"Verify vertex B or second ordered vertex is (9,-5), preserving coordinate roles."}},{"code":"B3","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Translates vertex C(2,5) to (5,-2)","check":{"type":"manual-verification","evidence":"Verify vertex C or third ordered vertex is (5,-2), preserving coordinate roles."}}],"p2-q3-v2::c":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Uses Pythagoras with horizontal change 4 and vertical change 3","check":{"type":"manual-verification","evidence":"Check BC²=(6-2)²+(2-5)²=4²+3²; allow any equivalent correctly constructed distance formula."}},{"code":"M2","kind":"M","marks":1,"field":"working","depends":["M1"],"profile":"source-calibrated","description":"Finds BC²=25 from 16+9","check":{"type":"manual-verification","evidence":"Check the squared distance is 25 and the positive square root is used. Reject adding signed differences without squaring."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M2"],"profile":"source-calibrated","description":"Reports length BC=5.00 units to two decimal places","check":{"type":"numeric","value":5,"tolerance":0.000001,"dp":2}}],"p2-q4-v2::a1":[{"code":"B1","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Evaluates f(6)=3(6)-5=13","check":{"type":"numeric","value":13,"tolerance":0.011}}],"p2-q4-v2::a2":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Evaluates the inner function g(3)=10","check":{"type":"containsValue","value":10}},{"code":"M2","kind":"M","marks":1,"field":"working","depends":["M1"],"profile":"source-calibrated","description":"Substitutes into the outer function f(10)=3(10)-5","check":{"type":"manual-verification","evidence":"Verify correct function order fg(3)=f(g(3)), g(3)=10 then f(10)=3(10)-5; do not award method for f(3)g(3) or g(f(3))."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M2"],"profile":"source-calibrated","description":"Obtains fg(3)=25","check":{"type":"numeric","value":25,"tolerance":0.011}}],"p2-q4-v2::b":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Sets y=3x-5 and interchanges x and y","check":{"type":"manual-verification","evidence":"Look for y=3x-5 followed by x=3y-5, or an equivalent inverse-operation argument."}},{"code":"M2","kind":"M","marks":1,"field":"working","depends":["M1"],"profile":"source-calibrated","description":"Rearranges to 3y=x+5","check":{"type":"manual-verification","evidence":"Check correct inverse operation: add 5 then divide by 3; equivalent rearrangement earns the mark."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M2"],"profile":"source-calibrated","description":"Gives inverse f⁻¹(x)=(x+5)/3","check":{"type":"expression","value":"(x+5)/3"}}],"p2-q4-v2::c":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Solves g(x)=26 as x²=25","check":{"type":"manual-verification","evidence":"Check x²+1=26→x²=25 and recognition that both roots must be considered."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M1"],"profile":"source-calibrated","description":"States both roots x=5 and x=-5 in either order","check":{"type":"set","value":[5,-5],"tolerance":0.000001}}],"p2-q5-v2::a":[{"0":"a","1":"n","2":"s","3":"w","4":"e","5":"r","code":"B1","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Identifies the modal class 11–15 kg","check":{"type":"sparkAnswer","answer":"11 - 15","accepted":["11-15","11 to 15","11–15"]}}],"p2-q5-v2::b":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Uses the correct five class midpoints 3,8,13,18,23","check":{"type":"manual-verification","evidence":"Verify correct midpoint for each of the five class intervals and the corresponding frequencies 5,9,12,9,5."}},{"code":"M2","kind":"M","marks":1,"field":"working","depends":["M1"],"profile":"source-calibrated","description":"Calculates weighted total Σfx=520 from midpoint×frequency","check":{"type":"manual-verification","evidence":"Check 5×3+9×8+12×13+9×18+5×23=520 with total frequency 40."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M2"],"profile":"source-calibrated","description":"Estimates mean mass 520÷40=13 kg","check":{"type":"numeric","value":13,"tolerance":0.011}}],"p2-q5-v2::c":[{"code":"B1","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Fills cumulative-frequency cells at 10.5 and 15.5 kg as 14 and 26","check":{"type":"manual-verification","evidence":"Verify entries 14 and 26 in the correct rows and columns; the first cumulative frequency 5 is given and should not earn another mark."}},{"code":"B2","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Fills cumulative frequency at 20.5 kg as 35","check":{"type":"manual-verification","evidence":"Verify the submitted cell for not more than 20.5 kg is 35."}},{"code":"B3","kind":"B","marks":1,"field":"all","depends":[],"profile":"source-calibrated","description":"Fills final cumulative frequency at 25.5 kg as 40","check":{"type":"manual-verification","evidence":"Verify the submitted final cumulative frequency cell is 40. Do not award for an unrelated total."}}],"p2-q5-v2::d":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Finds 14 of the 40 parcels exceed 15 kg","check":{"type":"manual-verification","evidence":"Verify frequency 9+5=14 in mass classes 16-20 and 21-25 and denominator 40; other valid proportional methods allowed."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M1"],"profile":"source-calibrated","description":"Gives simplified probability 7/20","check":{"type":"fraction","value":0.35,"requireFraction":true,"simplified":true}}],"p2-q6-v2::a":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Applies base-area formula A=πr² with π=22/7 and r=7","check":{"type":"manual-verification","evidence":"Check area formula and substitution; do not use circumference 2πr or diameter as the radius."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M1"],"profile":"source-calibrated","description":"Obtains circular area 154 m²","check":{"type":"numeric","value":154,"tolerance":0.011}}],"p2-q6-v2::b":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Uses volume of cylinder as base area times height","check":{"type":"manual-verification","evidence":"Accept V=πr²h with r=7,h=15,π=22/7 or previous base area multiplied by 15."}},{"code":"M2","kind":"M","marks":1,"field":"working","depends":["M1"],"profile":"source-calibrated","description":"Multiplies area 154 by height 15","check":{"type":"manual-verification","evidence":"Check 154×15=2310 or valid consistent follow-through from an earlier wrong circular area."},"followThroughUses":["a"],"followThroughFormula":"15*a"},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M2"],"profile":"source-calibrated","description":"Obtains 2310 m³ or valid ECF from part (a)","check":{"type":"numeric","value":2310,"tolerance":0.011},"ecf":{"uses":["a"],"formula":"15*a"}}],"p2-q6-v2::c":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Uses curved area 2πrh rather than the full closed surface","check":{"type":"manual-verification","evidence":"Check 2×(22/7)×7×15, recognising that the curved wall excludes both circular ends."}},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M1"],"profile":"source-calibrated","description":"Obtains curved surface area 660 m²","check":{"type":"numeric","value":660,"tolerance":0.011}}],"p2-q6-v2::d":[{"code":"M1","kind":"M","marks":1,"field":"working","depends":[],"profile":"source-calibrated","description":"Divides the tank volume by rate 21 m³ per hour","check":{"type":"calculation","values":[2310,21]},"followThroughUses":["b"],"followThroughFormula":"b/21"},{"code":"A1","kind":"A","marks":1,"field":"answer","depends":["M1"],"profile":"source-calibrated","description":"Obtains 110 hours or valid ECF from tank volume","check":{"type":"numeric","value":110,"tolerance":0.011},"ecf":{"uses":["b"],"formula":"b/21"}}]}'::jsonb;
 v_answers jsonb := '{"p2-q3-v2::a":"A reflection in the y-axis (x = 0)","p2-q3-v2::b":"(5, -5); (9, -5); (5, -2)","p2-q3-v2::c":"5.00","p2-q4-v2::a1":"13","p2-q4-v2::a2":"25","p2-q4-v2::b":"(x + 5)/3","p2-q4-v2::c":"5 and -5","p2-q5-v2::a":"11 - 15","p2-q5-v2::b":"13","p2-q5-v2::c":"5, 14, 26, 35, 40","p2-q5-v2::d":"7/20","p2-q6-v2::a":"154","p2-q6-v2::b":"2310","p2-q6-v2::c":"660","p2-q6-v2::d":"110"}'::jsonb;
 v_original spark_grading_private.rubrics_v2%rowtype;
 v_updated jsonb;
 v_count int;
 v_invalid int;
BEGIN
 SELECT * INTO v_original
 FROM spark_grading_private.rubrics_v2
 WHERE subject_id='mathematics' AND paper_id='original-v2'
   AND rubric_version='source-scheme-draft-v2' FOR UPDATE;
 IF NOT FOUND OR v_original.active OR
   v_original.verification_status<>'draft' OR
   v_original.verified_by IS NOT NULL OR v_original.verified_at IS NOT NULL
   OR v_original.source_sha256 IS DISTINCT FROM
     encode(pg_catalog.sha256(convert_to(v_original.criteria::text,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'Math original-v2 source digest or review gate changed';
 END IF;
 IF jsonb_array_length(v_original.criteria)<>42 THEN
  RAISE EXCEPTION 'Math original-v2 number of source parts changed';
 END IF;
 SELECT count(*),
   count(*) FILTER(WHERE
     part->>'id' IS DISTINCT FROM part->>'sourcePartId'
     OR part->'sourceMarking'->>'answer' IS DISTINCT FROM v_answers->>(part->>'id')
     OR jsonb_typeof(part->'sourceMarking'->'criteria') IS DISTINCT FROM 'null'
     OR (part->>'maxMarks')::integer IS DISTINCT FROM
      (SELECT sum((c->>'marks')::integer)
       FROM jsonb_array_elements(v_schemes->(part->>'id'))c)
   ) INTO v_count,v_invalid
 FROM jsonb_array_elements(v_original.criteria)part
 WHERE v_schemes ? (part->>'id');
 IF v_count<>15 OR v_invalid<>0 THEN
  RAISE EXCEPTION 'Math Q3-Q6 source/mark mismatch %/15 and % invalid',
   v_count,v_invalid;
 END IF;
 SELECT jsonb_agg(
  CASE WHEN v_schemes ? (part.value->>'id')
   THEN jsonb_set(part.value,'{sourceMarking,criteria}',
      v_schemes->(part.value->>'id'))
   ELSE part.value END ORDER BY part.ordinal
 ) INTO v_updated
 FROM jsonb_array_elements(v_original.criteria)
   WITH ORDINALITY part(value,ordinal);
 IF jsonb_array_length(v_updated)<>jsonb_array_length(v_original.criteria) THEN
  RAISE EXCEPTION 'Original v2 criterion array length mismatch';
 END IF;
 UPDATE spark_grading_private.rubrics_v2
 SET criteria=v_updated,
   source_sha256=encode(pg_catalog.sha256(convert_to(v_updated::text,'UTF8')),'hex')
 WHERE subject_id='mathematics' AND paper_id='original-v2'
   AND rubric_version='source-scheme-draft-v2'
   AND active=false AND verification_status='draft';
 IF NOT FOUND THEN RAISE EXCEPTION 'Math original-v2 draft-only update failed'; END IF;
END $math_source$;
COMMIT;
